/**
 * Offline fixture source: payloads are JSON files bundled with the app
 * (generated by scripts/generate-fixtures.ts). No network is involved.
 *
 * `simulate` exists for QA of loading / error / empty states (Settings page).
 */
import { ABSENT, type PayloadName, type PayloadSource } from "./index";

export const SIMULATE_MODES = ["none", "slow", "error", "empty"] as const;
export type SimulateMode = (typeof SIMULATE_MODES)[number];

const LOADERS: Record<Exclude<PayloadName, "lab-events">, () => Promise<{ default: unknown }>> = {
  "jobs.feed": () => import("@/fixtures/generated/jobs.feed.json"),
  claims: () => import("@/fixtures/generated/claims.json"),
  evidence: () => import("@/fixtures/generated/evidence.json"),
  preferences: () => import("@/fixtures/generated/preferences.json"),
  matches: () => import("@/fixtures/generated/matches.json"),
  scenarios: () => import("@/fixtures/generated/scenarios.json"),
  "atlas.pca": () => import("@/fixtures/generated/atlas.pca.json"),
  "atlas.axes": () => import("@/fixtures/generated/atlas.axes.json"),
  experiments: () => import("@/fixtures/generated/experiments.json"),
  assignments: () => import("@/fixtures/generated/assignments.json"),
  outcomes: () => import("@/fixtures/generated/outcomes.json"),
  "resume-variants": () => import("@/fixtures/generated/resume-variants.json"),
  "application-events": () => import("@/fixtures/generated/application-events.json"),
  manifest: () => import("@/fixtures/generated/manifest.json"),
};

const EMPTY_LISTS: PayloadName[] = [
  "jobs.feed", "claims", "evidence", "matches", "scenarios", "experiments", "assignments", "outcomes", "resume-variants", "application-events",
];

export function createFixtureSource(simulate: SimulateMode = "none"): PayloadSource {
  return {
    id: "fixture",
    label: "Offline synthetic fixtures",
    async load(name) {
      // Fixtures have no simulated experiment-run stream.
      if (name === "lab-events") return ABSENT;
      if (simulate === "slow") await new Promise((r) => setTimeout(r, 1500));
      if (simulate === "error") throw new Error("Simulated load failure (QA setting)");
      if (simulate === "empty" && EMPTY_LISTS.includes(name)) return [];
      if (simulate === "empty" && (name === "atlas.pca" || name === "atlas.axes")) return null;
      return (await LOADERS[name]()).default;
    },
  };
}
